using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using EternalSteam;
using EternalSteam.OpenWorld;
using EternalSteam.Railway;
public static class VerifyRailwayPlay
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 public static string Main(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(Application.isPlaying,"Play required");Check(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")?.StartsWith("/tmp/eternal-railway-")==true,"Isolated save root required");s.Persistence.Automatic=false;s.Clock.Paused=true;Check(!s.Persistence.Blocked,s.Persistence.Status);
 var c=s.Content;var input=s.GetComponent<OpenWorldInput>();input.Cancel();Check(c.GroundWorld.Buildings.Count==1,"Fresh fixture required");
 var mainId=c.MainBase.Module<IBaseIdentity>().BaseId;
 var subDef=s.ContentCatalog.Buildings.Single(d=>d.Id=="installation.nexus");BuildingInstance sub=null;
 for(int z=20;z>=12&&sub==null;z--)for(int x=-5;x<10&&sub==null;x++)if(c.GroundPlacement.Add(subDef,new Vector2Int(x,z),out _).Success){var result=c.GroundPlacement.Confirm();Check(result.Success,result.Message);sub=c.GroundWorld.Buildings.Last();}
 Check(sub!=null,"Sub base placement");var subId=sub.Module<IBaseIdentity>().BaseId;c.Bases.Refresh();c.Bases.Select(mainId);
 var aBank=c.Inventories.Available(mainId);var bBank=c.Inventories.Available(subId);aBank.Deposit("iron",500);aBank.Deposit("coal",100);bBank.Deposit("iron",100);
 var station=s.RailwayHud.Station;var track=s.RailwayHud.Track;
 var relative=new List<Vector2Int>();for(int x=2;x<=5;x++)relative.Add(new Vector2Int(x,1));relative.Add(new Vector2Int(5,0));for(int y=1;y<=4;y++)relative.Add(new Vector2Int(8,y));for(int x=7;x>=-1;x--)relative.Add(new Vector2Int(x,4));for(int y=3;y>=0;y--)relative.Add(new Vector2Int(-1,y));
 Vector2Int? offset=null;
 for(int z=12;z<26&&!offset.HasValue;z++)for(int x=-5;x<8&&!offset.HasValue;x++){var o=new Vector2Int(x,z);if(!c.GroundPlacement.Validate(new PlacementRequest(-1,station,o)).Success||!c.GroundPlacement.Validate(new PlacementRequest(-2,station,o+new Vector2Int(6,0))).Success)continue;if(relative.All(p=>c.GroundPlacement.Validate(new PlacementRequest(-3,track,p+o)).Success))offset=o;}
 Check(offset.HasValue,"Find terrain-valid circular fixture");var origin=offset.Value;
 BuildingInstance Install(BuildingDefinition def,Vector2Int cell,string owner){c.Bases.Select(owner);input.BeginEditing();double before=c.Inventories.Available(owner).Amount("iron");Check(input.Edits.AddContent(def,c.GroundWorld.Grid.Center(cell,Vector2Int.one),WorldGridGeometry.Rotation*Vector3.forward,out var why),why);Check(c.Inventories.Available(owner).Amount("iron")==before,"No reservation charge");var result=input.Edits.Confirm();Check(result.Success,result.Message);Check(c.Inventories.Available(owner).Amount("iron")==before-(def==station?10:1),"Owner charged once");input.Cancel();return c.GroundWorld.Buildings.Last();}
 var a=Install(station,origin,mainId);var b=Install(station,origin+new Vector2Int(6,0),subId);foreach(var p in relative)Install(track,p+origin,mainId);
 c.Railway.Refresh();var n=c.Railway.Network;var stops=new[]{new RailStop{stationId=a.PersistentId,load=100},new RailStop{stationId=b.PersistentId,unload=100}};
 Check(n.Commit(Guid.NewGuid().ToString("N"),stops,out var r,out var error),error);Check(n.Configure(r,"iron",0,100,0,out error),error);Check(n.Refuel(r,50,out error),error);double stockA=aBank.Amount("iron"),stockB=bBank.Amount("iron");Check(n.Start(r,out error),error);c.Railway.Tick(11.25);Check(r.train.status==TrainStatus.Moving,"Train moving");
 Check(Math.Abs(stockA-aBank.Amount("iron")-r.train.cargo)<.0001,"Cargo conservation before delivery");Check(s.RailwayView.transform.childCount>=2,"Authored train prefab instantiated");
 s.Clock.SetPhase(DayPhase.Day);s.Enemies.Reset();Check(s.Persistence.Save(),s.Persistence.Status);File.WriteAllText("/tmp/eternal-railway-moving-before.json",JsonUtility.ToJson(s.Persistence.Capture()));
 return "PASS real placement reservations/owner payments; two independent bases; closed route; live train/cargo; moving save. Reload next.";
 }
 public static string Reloaded(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;Check(!s.Persistence.Blocked,s.Persistence.Status);Check(s.Clock.Paused,"Restored paused");var before=JsonUtility.FromJson<SingleMapSnapshot>(File.ReadAllText("/tmp/eternal-railway-moving-before.json"));var after=s.Persistence.Capture();before.savedUtc=after.savedUtc;Check(JsonUtility.ToJson(before)==JsonUtility.ToJson(after),"Moving save exact roundtrip");var n=s.Content.Railway.Network;var r=n.Routes.Single();var dest=n.Station(r.stops[1].stationId);var bank=s.Content.Inventories.Available(dest.OwnerBaseId);double amount=bank.Amount("iron"),fuel=r.train.fuel;n.Stop(r);s.Content.Railway.Tick(10);Check(r.train.status==TrainStatus.Stopped&&r.train.stop==1&&r.train.cargo==0&&bank.Amount("iron")==amount+100,"Next station delivery after reload");Check(r.train.fuel==fuel,"No second fuel charge");Check(s.Persistence.Save(),s.Persistence.Status);File.WriteAllText("/tmp/eternal-railway-stopped-before.json",JsonUtility.ToJson(s.Persistence.Capture()));return "PASS moving save exact roundtrip, preserved fuel, next station stop and delivery; stopped save ready.";
 }
 public static string StoppedReloaded(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;Check(!s.Persistence.Blocked,s.Persistence.Status);var before=JsonUtility.FromJson<SingleMapSnapshot>(File.ReadAllText("/tmp/eternal-railway-stopped-before.json"));var after=s.Persistence.Capture();before.savedUtc=after.savedUtc;Check(JsonUtility.ToJson(before)==JsonUtility.ToJson(after),"Stopped roundtrip");var n=s.Content.Railway.Network;var r=n.Routes.Single();var bank=s.Content.Inventories.Available(n.Station(r.stops[1].stationId).OwnerBaseId);double amount=bank.Amount("iron");Check(n.Start(r,out var error),error);Check(bank.Amount("iron")==amount,"No duplicate unload on restart");n.Stop(r);s.RailwayHud.Execute("open");s.RailwayHud.Execute("row:0");return "PASS stopped roundtrip, no duplicate service, detail UI opened.";}
 public static string PrepareMigration(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(Application.isPlaying&&Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")?.StartsWith("/tmp/eternal-")==true,"Isolated Play required");s.Persistence.Automatic=false;Check(!s.Persistence.Blocked&&s.Content.GroundWorld.Buildings.Count<=2,"Fresh base fixture required");
 var sub=s.ContentCatalog.Buildings.Single(d=>d.Id=="installation.nexus");bool placed=s.Content.GroundWorld.Buildings.Count==2;
 for(int z=20;z>=12&&!placed;z--)for(int x=-5;x<10&&!placed;x++)if(s.Content.GroundPlacement.Add(sub,new Vector2Int(x,z),out _).Success){var result=s.Content.GroundPlacement.Confirm();Check(result.Success,result.Message);placed=true;}
 Check(placed,"Sub base fixture placement");s.Content.Bases.Refresh();var d=s.Persistence.Capture();d.buildings.RemoveAll(b=>b.definition.StartsWith("railway."));d.version=1;d.railway=new RailwayNetwork.Snapshot();d.inventories.Clear();d.migratedVersion=0;d.migratedFrom=null;d.stocks=s.Content.Resources.Capture().Select(v=>new ResourceBank.Stock{id=v.id,amount=v.id=="iron"?1234:0,capacity=v.capacity}).ToList();Check(d.stocks.Any(v=>v.id=="iron"),"Iron resource exists");s.Persistence.Validate(d);
 string payload=JsonUtility.ToJson(d),root="/tmp/eternal-railway-migration-"+Guid.NewGuid().ToString("N");new JsonSaveStore(root).Write(d.runId,payload);File.WriteAllText("/tmp/eternal-railway-v1-payload.json",payload);Environment.SetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT",root);UnityEditor.SceneManagement.EditorSceneManager.LoadSceneInPlayMode(s.gameObject.scene.path,new UnityEngine.SceneManagement.LoadSceneParameters(UnityEngine.SceneManagement.LoadSceneMode.Single));return "Synthetic v1 fixture written, loading through actual initialization";
 }
 public static string Migrated(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(!s.Persistence.Blocked,s.Persistence.Status);s.Persistence.Automatic=false;var d=s.Persistence.Capture();string original=File.ReadAllText("/tmp/eternal-railway-v1-payload.json");Check(d.version==2&&d.migratedVersion==1&&d.migratedFrom==JsonSaveStore.Digest(original),"Migration marker");string main=s.Content.MainBase.Module<IBaseIdentity>().BaseId;Check(d.inventories.Single(i=>i.baseId==main).stocks.Single(v=>v.id=="iron").amount==1234,"Main receives all old stock including overflow");Check(d.inventories.Where(i=>i.baseId!=main).SelectMany(i=>i.stocks).All(v=>v.amount==0),"Sub inventory not duplicated");Check(d.stocks.Single(v=>v.id=="iron").amount==0,"Legacy shared stock cleared");Check(s.Persistence.Save(),s.Persistence.Status);string root=Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT");var sources=Directory.GetFiles(Path.Combine(root,"migrations"),"source-payload.json",SearchOption.AllDirectories);Check(sources.Length==1&&File.ReadAllText(sources[0])==original,"Immutable source archive");Check(JsonUtility.FromJson<SingleMapSnapshot>(new JsonSaveStore(root).Read().Payload).version==2,"v2 persisted");s.Persistence.ContinueSaved();return "PASS actual v1 initialization migration, overflow 1234 retained only at main, source archive and v2 write; reload requested.";
 }
 public static string MigrationReloaded(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(!s.Persistence.Blocked,s.Persistence.Status);var d=s.Persistence.Capture();string original=File.ReadAllText("/tmp/eternal-railway-v1-payload.json");string main=s.Content.MainBase.Module<IBaseIdentity>().BaseId;Check(d.version==2&&d.migratedVersion==1&&d.migratedFrom==JsonSaveStore.Digest(original),"Source marker stable");Check(d.inventories.Single(i=>i.baseId==main).stocks.Single(v=>v.id=="iron").amount==1234,"No duplicate grant on v2 reload");Check(d.stocks.Single(v=>v.id=="iron").amount==0,"Shared bank stays empty");return "PASS v2 reload retains source hash and main stock exactly once";}
}
